    async def fetch_tickers(self, symbols: Strings = None, params={}) -> Tickers:
        """
        fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market

        https://massive.com/docs/rest/stocks/snapshots/full-market-snapshot
        https://massive.com/docs/rest/stocks/aggregates/daily-market-summary

        :param str[] [symbols]: unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.method]: 'snapshot'(default) or 'groupedDailyBars', snapshots need a snapshot entitlement on the massive plan
        :param str [params.date]: only read by 'groupedDailyBars', the trading day to summarise, e.g. 2026-08-28, defaults to today
        :returns dict: a dictionary of [ticker structures](https://docs.ccxt.com/#/?id=ticker-structure)
        """
        await self.load_markets()
        symbols = self.market_symbols(symbols)
        method = None
        method, params = self.handle_option_and_params(params, 'fetchTickers', 'method', 'snapshot')
        if method == 'groupedDailyBars':
            groupedRequest = {
                'date': self.safe_string(params, 'date', self.yyyymmdd(self.milliseconds())),
            }
            params = self.omit(params, ['date'])
            grouped = await self.publicGetV2AggsGroupedLocaleUsMarketStocksDate(self.extend(groupedRequest, params))
            #
            #     {
            #         "queryCount": 12518,
            #         "resultsCount": 12518,
            #         "adjusted": True,
            #         "results": [
            #             {"T": "GBCI", "v": 898130, "vw": 46.9919, "o": 47.5, "c": 46.88, "h": 47.71, "l": 46.85, "t": 1787947200000, "n": 16823}
            #         ],
            #         "status": "OK"
            #     }
            #
            groupedResults = self.safe_list(grouped, 'results', [])
            return self.parse_tickers(groupedResults, symbols)
        request = {}
        if symbols is not None:
            ids = self.market_ids(symbols)
            request['tickers'] = ','.join(ids)
        response = await self.publicGetV2SnapshotLocaleUsMarketsStocksTickers(self.extend(request, params))
        #
        #     {
        #         "count": 1,
        #         "status": "OK",
        #         "tickers": [
        #             {
        #                 "ticker": "BCAT",
        #                 "day": {"o": 20.64, "h": 20.64, "l": 20.506, "c": 20.506, "v": 37216, "vw": 20.616},
        #                 "prevDay": {"o": 20.79, "h": 21, "l": 20.5, "c": 20.63, "v": 292738, "vw": 20.6939},
        #                 "lastQuote": {"p": 20.5, "s": 13, "P": 20.6, "S": 22, "t": 1605192959994246100},
        #                 "lastTrade": {"p": 20.506, "s": 2416, "x": 4, "t": 1605192894630916600, "i": "71675577320245"},
        #                 "todaysChange": -0.124,
        #                 "todaysChangePerc": -0.601,
        #                 "updated": 1605192894630916600
        #             }
        #         ]
        #     }
        #
        tickers = self.safe_list(response, 'tickers', [])
        return self.parse_tickers(tickers, symbols)

    def parse_ticker(self, ticker: dict, market: Market = None) -> Ticker:
        day = self.safe_dict(ticker, 'day')
        if day is None:
            # aggregate bar shape, returned by the previous day bar and the daily market summary endpoints
            barMarketId = self.safe_string(ticker, 'T')
            barTimestamp = self.safe_integer(ticker, 't')
            barClose = self.safe_string(ticker, 'c')
            return self.safe_ticker({
                'symbol': self.safe_symbol(barMarketId, market),
                'timestamp': barTimestamp,
                'datetime': self.iso8601(barTimestamp),
                'high': self.safe_string(ticker, 'h'),
                'low': self.safe_string(ticker, 'l'),
                'bid': None,
                'bidVolume': None,
                'ask': None,
                'askVolume': None,
                'vwap': self.safe_string(ticker, 'vw'),
                'open': self.safe_string(ticker, 'o'),
                'close': barClose,
                'last': barClose,
                'previousClose': None,
                'change': None,
                'percentage': None,
                'average': None,
                'baseVolume': self.safe_string(ticker, 'v'),
                'quoteVolume': None,
                'info': ticker,
            }, market)
        # snapshot shape
        marketId = self.safe_string(ticker, 'ticker')
        lastQuote = self.safe_dict(ticker, 'lastQuote', {})
        lastTrade = self.safe_dict(ticker, 'lastTrade', {})
        previousDay = self.safe_dict(ticker, 'prevDay', {})
        timestamp = self.safe_integer_product(ticker, 'updated', 0.000001)
        last = self.safe_string(lastTrade, 'p')
        return self.safe_ticker({
            'symbol': self.safe_symbol(marketId, market),
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'high': self.safe_string(day, 'h'),
            'low': self.safe_string(day, 'l'),
            'bid': self.safe_string(lastQuote, 'p'),
            'bidVolume': self.safe_string(lastQuote, 's'),
            'ask': self.safe_string(lastQuote, 'P'),
            'askVolume': self.safe_string(lastQuote, 'S'),
            'vwap': self.safe_string(day, 'vw'),
            'open': self.safe_string(day, 'o'),
            'close': self.safe_string(day, 'c'),
            'last': last,
            'previousClose': self.safe_string(previousDay, 'c'),
            'change': self.safe_string(ticker, 'todaysChange'),
            'percentage': self.safe_string(ticker, 'todaysChangePerc'),
            'average': None,
            'baseVolume': self.safe_string(day, 'v'),
            'quoteVolume': None,
            'info': ticker,
        }, market)

    async def fetch_ohlcv(self, symbol: str, timeframe='1d', since: Int = None, limit: Int = None, params={}) -> list[list]:
        """
        fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market

        https://massive.com/docs/rest/stocks/aggregates/custom-bars

        :param str symbol: unified symbol of the market to fetch OHLCV data for
        :param str timeframe: the length of time each candle represents
        :param int [since]: timestamp in ms of the earliest candle to fetch
        :param int [limit]: the maximum amount of candles to fetch, max 50000
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param int [params.until]: timestamp in ms of the latest candle to fetch
        :param boolean [params.adjusted]: whether the bars are adjusted for splits, defaults to True
        :returns int[][]: A list of candles ordered, open, high, low, close, volume
        """
        await self.load_markets()
        market = self.market(symbol)
        selectedTimeframe = self.safe_string(self.timeframes, timeframe, timeframe)
        parts = selectedTimeframe.split('/')
        partsLength = len(parts)
        if partsLength < 2:
            raise BadRequest(self.id + ' fetchOHLCV() does not support the ' + timeframe + ' timeframe')
        maxLimit = self.safe_integer(self.options, 'maxOHLCVLimit', 50000)
        if limit is None:
            limit = self.safe_integer(self.options, 'defaultLimit', 1000)
        limit = min(limit, maxLimit)
        until = self.safe_integer(params, 'until')
        params = self.omit(params, ['until'])
        now = self.milliseconds()
        duration = self.parse_timeframe(timeframe) * 1000
        sort = 'asc'
        if since is None:
            # ask for the most recent candles instead of the oldest ones inside the window.
            # us equities trade ~6.5 hours a day, 5 days a week, so a window `limit` candles
            # wide in wall clock time always comes back short - widen it and the exchange
            # cut it down to `limit`, parseOHLCVs sorts the result back into ascending order
            sort = 'desc'
            if until is None:
                until = now
            windowFactor = self.safe_integer(self.options, 'ohlcvWindowFactor', 10)
            since = until - (limit * duration * windowFactor)
            if since < 0:
                since = 0
        elif until is None:
            computedUntil = self.sum(since, limit * duration)
            if computedUntil > now:
                until = now
            else:
                until = computedUntil
        # massive counts `limit` in base aggregates - seconds for the second timespan,
        # minutes for minute and hour, days for day and everything above it - and not in
        # returned candles, so a weekly request for 3 candles comes back with a single one
        timespan = parts[1]
        baseDuration = 24 * 60 * 60 * 1000
        if timespan == 'second':
            baseDuration = 1000
        elif (timespan == 'minute') or (timespan == 'hour'):
            baseDuration = 60 * 1000
        requestLimit = self.parse_to_int(limit * duration / baseDuration)
        requestLimit = min(requestLimit, maxLimit)
        request = {
            'stocksTicker': market['id'],
            'multiplier': parts[0],
            'timespan': parts[1],
            'from': since,
            'to': until,
            'limit': requestLimit,
            'sort': sort,
            'adjusted': True,
        }
        response = await self.publicGetV2AggsTickerStocksTickerRangeMultiplierTimespanFromTo(self.extend(request, params))
        #
        #     {
        #         "ticker": "AAPL",
        #         "queryCount": 3,
        #         "resultsCount": 3,
        #         "adjusted": True,
        #         "results": [
        #             {"v": 75051951, "vw": 305.1311, "o": 309.58, "c": 303.42, "h": 311.8, "l": 302.56, "t": 1785729600000, "n": 1388685}
        #         ],
        #         "status": "OK"
        #     }
        #
        results = self.safe_list(response, 'results', [])
        # when no `since` was given the newest candles are the interesting ones, so trim
        # the over-fetched tail-end of the window from the front instead of from the back
        tail = (sort == 'desc')
        return self.parse_ohlcvs(results, market, timeframe, since, limit, tail)

    def parse_ohlcv(self, ohlcv: object, market: Market = None) -> list:
        return [
            self.safe_integer(ohlcv, 't'),
            self.safe_number(ohlcv, 'o'),
            self.safe_number(ohlcv, 'h'),
            self.safe_number(ohlcv, 'l'),
            self.safe_number(ohlcv, 'c'),
            self.safe_number(ohlcv, 'v'),
        ]

    async def fetch_trades(self, symbol: str, since: Int = None, limit: Int = None, params={}) -> list[Trade]:
        """
        get the list of most recent trades for a particular symbol

        https://massive.com/docs/rest/stocks/trades-quotes/trades

        :param str symbol: unified symbol of the market to fetch trades for
        :param int [since]: timestamp in ms of the earliest trade to fetch
        :param int [limit]: the maximum amount of trades to fetch, max 50000
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param int [params.until]: timestamp in ms of the latest trade to fetch
        :returns dict[]: a list of [trade structures](https://docs.ccxt.com/#/?id=public-trades)
        """
        await self.load_markets()
        market = self.market(symbol)
        request = {
            'stocksTicker': market['id'],
            'sort': 'timestamp',
            'order': 'desc',
        }
        if limit is not None:
            maxLimit = self.safe_integer(self.options, 'maxTradesLimit', 50000)
            request['limit'] = min(limit, maxLimit)
        if since is not None:
            # the api works in nanoseconds, which overflows a double, keep it a string
            request['timestamp.gte'] = Precise.string_mul(self.number_to_string(since), '1000000')
            request['order'] = 'asc'
        until = self.safe_integer(params, 'until')
        params = self.omit(params, ['until'])
        if until is not None:
            request['timestamp.lte'] = Precise.string_mul(self.number_to_string(until), '1000000')
        response = await self.publicGetV3TradesStocksTicker(self.extend(request, params))
        #
        #     {
        #         "request_id": "a47d1beb8c11b6ae897ab76cdbbf35a3",
        #         "status": "OK",
        #         "results": [
        #             {
        #                 "id": "1",
        #                 "exchange": 11,
        #                 "tape": 3,
        #                 "price": 171.55,
        #                 "size": 100,
        #                 "conditions": [12, 41],
        #                 "correction": 0,
        #                 "sequence_number": 1063,
        #                 "participant_timestamp": 1517562000015577000,
        #                 "sip_timestamp": 1517562000016036600
        #             }
        #         ]
        #     }
        #
        results = self.safe_list(response, 'results', [])
        return self.parse_trades(results, market, since, limit)

    def parse_trade(self, trade: dict, market: Market = None) -> Trade:
        marketId = self.safe_string(trade, 'T')
        resolved = self.safe_market(marketId, market)
        timestamp = self.safe_integer_product_2(trade, 'sip_timestamp', 'participant_timestamp', 0.000001)
        return self.safe_trade({
            'id': self.safe_string_2(trade, 'id', 'i'),
            'info': trade,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'symbol': resolved['symbol'],
            'order': None,
            'type': None,
            # the consolidated tape does not disclose the aggressor of a trade
            'side': None,
            'takerOrMaker': None,
            'price': self.safe_string_2(trade, 'price', 'p'),
            'amount': self.safe_string_2(trade, 'size', 's'),
            'cost': None,
            'fee': None,
        }, resolved)

    async def fetch_order_book(self, symbol: str, limit: Int = None, params={}) -> OrderBook:
        """
        fetches the top of the consolidated order book, massive publishes the national best bid and offer, not the full depth of book

        https://massive.com/docs/rest/stocks/trades-quotes/last-quote

        :param str symbol: unified symbol of the market to fetch the order book for
        :param int [limit]: not used by massive.fetchOrderBook, the nbbo carries a single level per side
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: A dictionary of [order book structures](https://docs.ccxt.com/#/?id=order-book-structure) indexed by market symbols
        """
        await self.load_markets()
        market = self.market(symbol)
        request = {
            'stocksTicker': market['id'],
        }
        response = await self.publicGetV2LastNbboStocksTicker(self.extend(request, params))
        #
        #     {
        #         "request_id": "b84e24636301f19f88e0dfbf9a45ed5c",
        #         "status": "OK",
        #         "results": {
        #             "P": 127.98,
        #             "S": 7,
        #             "T": "AAPL",
        #             "X": 19,
        #             "p": 127.96,
        #             "q": 83480742,
        #             "s": 1,
        #             "t": 1617827221349730300,
        #             "x": 11,
        #             "y": 1617827221349366000,
        #             "z": 3
        #         }
        #     }
        #
        result = self.safe_dict(response, 'results', {})
        timestamp = self.safe_integer_product(result, 't', 0.000001)
        bids = []
        asks = []
        bidPrice = self.safe_string(result, 'p')
        bidAmount = self.safe_string(result, 's')
        if (bidPrice is not None) and Precise.string_gt(bidPrice, '0'):
            bids.append([bidPrice, bidAmount])
        askPrice = self.safe_string(result, 'P')
        askAmount = self.safe_string(result, 'S')
        if (askPrice is not None) and Precise.string_gt(askPrice, '0'):
            asks.append([askPrice, askAmount])
        rawOrderBook = {
            'bids': bids,
            'asks': asks,
        }
        orderbook = self.parse_order_book(rawOrderBook, market['symbol'], timestamp)
        orderbook['nonce'] = self.safe_integer(result, 'q')
        return orderbook

    def sign(self, path: object, api: object = 'public', method='GET', params={}, headers: dict = None, body: Str = None):
        # every massive endpoint is authenticated, the api key entitles the
        # caller to a data feed, it is not bound to a trading account
        self.check_required_credentials()
        request = '/' + self.implode_params(path, params)
        url = self.implode_hostname(self.urls['api']['public']) + request
        query = self.omit(params, self.extract_params(path))
        queryLength = len(query)
        if queryLength > 0:
            url += '?' + self.urlencode(query)
        headers = {
            'Authorization': 'Bearer ' + self.apiKey,
            'Accept': 'application/json',
        }
        return {'url': url, 'method': method, 'body': body, 'headers': headers}

    def handle_errors(self, code: int, reason: str, url: str, method: str, headers: dict, body: str, response: object, requestHeaders: object, requestBody: object):
        if response is None:
            return None  # fallback to the default error handler
        status = self.safe_string(response, 'status')
        # DELAYED is a successful response on the delayed data plans
        if (status == 'OK') or (status == 'DELAYED'):
            return None
        error = self.safe_string_2(response, 'error', 'message')
        if (status is None) and (error is None):
            return None
        #
        #     {"status": "NOT_AUTHORIZED", "request_id": "943c", "message": "You are not entitled to self data."}
        #     {"status": "ERROR", "request_id": "943c", "error": "Unknown API Key"}
        #
        feedback = self.id + ' ' + body
        self.throw_exactly_matched_exception(self.exceptions['exact'], error, feedback)
        self.throw_broadly_matched_exception(self.exceptions['broad'], error, feedback)
        self.throw_exactly_matched_exception(self.exceptions['exact'], status, feedback)
        raise ExchangeError(feedback)
